WITH src AS (SELECT * FROM stores WHERE city = 'Bangkok' AND (region IN ('South', 'North', 'West') OR YEAR(opened_date) = 2025)), summary AS (SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, AVG(sqft) AS avg_sqft, COUNT(*) AS store_count FROM src GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT opened_cohort, avg_sqft, store_count FROM summary;
